const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'Cloudflare Radar 2024 Year in Review'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Accent line at top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: theme.accent }
  });

  // Orange accent bar left side
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.7, y: 1.6, w: 0.08, h: 1.8,
    fill: { color: theme.light }
  });

  // Title
  slide.addText("Cloudflare Radar\n2024 Year in Review", {
    x: 1.1, y: 1.5, w: 7.5, h: 2.0,
    fontSize: 40, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    lineSpacingMultiple: 1.15
  });

  // Subtitle
  slide.addText("Internet patterns and trends observed through Cloudflare's global network", {
    x: 1.1, y: 3.5, w: 7, h: 0.6,
    fontSize: 16, fontFace: "Arial",
    color: theme.accent
  });

  // Bottom accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.35, w: 10, h: 0.04,
    fill: { color: theme.light }
  });

  // Year badge
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 8.2, y: 4.6, w: 1.2, h: 0.5,
    fill: { color: theme.light },
    rectRadius: 0.08
  });
  slide.addText("2024", {
    x: 8.2, y: 4.6, w: 1.2, h: 0.5,
    fontSize: 18, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a1628", secondary: "1a2a4a", accent: "6ecfef", light: "f48120", bg: "0e1e38" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

