const pptxgen = require("pptxgenjs");
const path = require("path");

const slideConfig = {
  type: 'content',
  index: 2,
  title: "17% Global Traffic Growth and Starlink's 3.3x Surge"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.9,
    fill: { color: theme.bg }
  });
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.1, w: 9, h: 0.7,
    fontSize: 20, fontFace: "Arial",
    color: "FFFFFF", bold: true
  });

  // Top accent line under title
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.9, w: 10, h: 0.04,
    fill: { color: theme.accent }
  });

  // Metric box 1 - 17% Growth
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.4, y: 1.2, w: 4.3, h: 1.4,
    fill: { color: theme.bg },
    rectRadius: 0.1,
    line: { color: theme.accent, width: 1.5 }
  });
  slide.addText("17%", {
    x: 0.6, y: 1.25, w: 4, h: 0.75,
    fontSize: 42, fontFace: "Arial",
    color: theme.light, bold: true
  });
  slide.addText("YoY Global Internet Traffic Growth", {
    x: 0.6, y: 1.95, w: 4, h: 0.5,
    fontSize: 14, fontFace: "Arial",
    color: "FFFFFF"
  });

  // Metric box 2 - 3.3x Starlink
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 5.3, y: 1.2, w: 4.3, h: 1.4,
    fill: { color: theme.bg },
    rectRadius: 0.1,
    line: { color: theme.light, width: 1.5 }
  });
  slide.addText("3.3x", {
    x: 5.5, y: 1.25, w: 4, h: 0.75,
    fontSize: 42, fontFace: "Arial",
    color: theme.accent, bold: true
  });
  slide.addText("Starlink Traffic Surge in 2024", {
    x: 5.5, y: 1.95, w: 4, h: 0.5,
    fontSize: 14, fontFace: "Arial",
    color: "FFFFFF"
  });

  // Bullet points - left column
  slide.addText([
    { text: "Traffic Growth Drivers", options: { fontSize: 13, bold: true, color: theme.accent, bullet: false, breakType: "none" } },
    { text: "" },
    { text: "Growth driven by increasing reliance on Internet for communication, commerce, entertainment, and transportation", options: { fontSize: 11, color: "C8D0DD", bullet: { type: "bullet" }, indentLevel: 0 } },
    { text: "" },
    { text: "Trend line starts mid-January to normalize for post-holiday activity patterns", options: { fontSize: 11, color: "C8D0DD", bullet: { type: "bullet" }, indentLevel: 0 } }
  ], {
    x: 0.4, y: 2.85, w: 4.3, h: 1.5,
    valign: "top", paraSpaceAfter: 4
  });

  // Starlink image
  slide.addImage({
    path: path.resolve(__dirname, "imgs/starlink-traffic-growth-2024.jpg"),
    x: 5.3, y: 2.85, w: 4.3, h: 2.3,
    rounding: true
  });

  // Caption under image
  slide.addText("Normalized Starlink traffic worldwide — 2024", {
    x: 5.3, y: 5.15, w: 4.3, h: 0.3,
    fontSize: 8, fontFace: "Arial",
    color: "7A8599", italic: true, align: "center"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a1628", secondary: "1a2a4a", accent: "6ecfef", light: "f48120", bg: "0e1e38" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

