  title: 'Post-Quantum Encryption Jumps from 2% to 13% of TLS 1.3'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.9,
    fill: { color: theme.bg }
  });
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.1, w: 9, h: 0.7,
    fontSize: 20, fontFace: "Arial",
    color: "FFFFFF", bold: true
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.9, w: 10, h: 0.04,
    fill: { color: theme.accent }
  });

  // Three metric cards
  const metrics = [
    { val: "2% \u2192 13%", label: "Post-Quantum\nTLS 1.3 Traffic", color: theme.light },
    { val: "21%", label: "HTTP/3\nAdoption Rate", color: theme.accent },
    { val: "Go #1", label: "API Client Language\n(~12% of traffic)", color: theme.light }
  ];

  metrics.forEach((m, i) => {
    const xPos = 0.4 + i * 3.15;
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: xPos, y: 1.15, w: 2.9, h: 1.25,
      fill: { color: theme.bg },
      rectRadius: 0.08,
      line: { color: m.color, width: 1.2 }
    });
    slide.addText(m.val, {
      x: xPos, y: 1.15, w: 2.9, h: 0.65,
      fontSize: 26, fontFace: "Arial",
      color: m.color, bold: true, align: "center", valign: "bottom"
    });
    slide.addText(m.label, {
      x: xPos, y: 1.8, w: 2.9, h: 0.55,
      fontSize: 10, fontFace: "Arial",
      color: "C8D0DD", align: "center", valign: "top",
      lineSpacingMultiple: 1.1
    });
  });

  // Left column - PQ adoption details
  slide.addText("Post-Quantum Adoption", {
    x: 0.4, y: 2.6, w: 4.3, h: 0.35,
    fontSize: 13, fontFace: "Arial",
    color: theme.accent, bold: true
  });

  slide.addText([
    { text: "Chrome 124 enabled PQ key agreement by default (Apr 17, 2024)", options: { fontSize: 10.5, color: "C8D0DD", bullet: { type: "bullet" } } },
