    { text: "Apple Safari began initial PQ testing", options: { fontSize: 10.5, color: "C8D0DD", bullet: { type: "bullet" } } }
  ], {
    x: 0.4, y: 2.95, w: 4.3, h: 1.2,
    valign: "top", paraSpaceAfter: 2
  });

  // API languages sub-section
  slide.addText("API Client Languages", {
    x: 0.4, y: 4.15, w: 4.3, h: 0.35,
    fontSize: 13, fontFace: "Arial",
    color: theme.light, bold: true
  });

  // Mini bar chart using shapes for API languages
  const langs = [
    { name: "Go", pct: 12, color: theme.accent },
    { name: "Python", pct: 9.6, color: "5BA8C8" },
    { name: "Java", pct: 7.4, color: "4A90A0" },
    { name: ".NET", pct: 3.6, color: "3A7080" }
  ];

  langs.forEach((l, i) => {
    const yPos = 4.52 + i * 0.23;
    slide.addText(l.name, {
      x: 0.5, y: yPos, w: 0.7, h: 0.2,
      fontSize: 8, fontFace: "Arial",
      color: "C8D0DD", align: "right", valign: "middle"
    });
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: 1.3, y: yPos + 0.03, w: (l.pct / 12) * 2.5, h: 0.14,
      fill: { color: l.color },
      rectRadius: 0.03
    });
    slide.addText(l.pct + "%", {
      x: 1.3 + (l.pct / 12) * 2.5 + 0.1, y: yPos, w: 0.6, h: 0.2,
      fontSize: 8, fontFace: "Arial",
      color: "C8D0DD", valign: "middle"
    });
  });

  // Right side - PQ encryption chart image
  slide.addImage({
    path: path.resolve(__dirname, "imgs/post-quantum-encryption-adoption.jpg"),
    x: 5.1, y: 2.6, w: 4.5, h: 2.7
  });

  // Caption
  slide.addText("Post-quantum encrypted traffic adoption after Chrome 124 release", {
    x: 5.1, y: 5.25, w: 4.5, h: 0.25,
    fontSize: 8, fontFace: "Arial",
    color: "7A8599", italic: true, align: "center"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
