const pptxgen = require("pptxgenjs");
const path = require("path");

const slideConfig = {
  type: 'content',
  index: 4,
  title: 'Post-Quantum Encryption Jumps from 2% to 13% of TLS 1.3'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.9,
    fill: { color: theme.bg }
  });
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.1, w: 9, h: 0.7,
    fontSize: 20, fontFace: "Arial",
    color: "FFFFFF", bold: true
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.9, w: 10, h: 0.04,
    fill: { color: theme.accent }
  });

  // Three metric cards
  const metrics = [
    { val: "2% \u2192 13%", label: "Post-Quantum\nTLS 1.3 Traffic", color: theme.light },
    { val: "21%", label: "HTTP/3\nAdoption Rate", color: theme.accent },
    { val: "Go #1", label: "API Client Language\n(~12% of traffic)", color: theme.light }
  ];

  metrics.forEach((m, i) => {
    const xPos = 0.4 + i * 3.15;
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: xPos, y: 1.15, w: 2.9, h: 1.25,
      fill: { color: theme.bg },
      rectRadius: 0.08,
      line: { color: m.color, width: 1.2 }
    });
    slide.addText(m.val, {
      x: xPos, y: 1.15, w: 2.9, h: 0.65,
      fontSize: 26, fontFace: "Arial",
      color: m.color, bold: true, align: "center", valign: "bottom"
    });
    slide.addText(m.label, {
      x: xPos, y: 1.8, w: 2.9, h: 0.55,
      fontSize: 10, fontFace: "Arial",
      color: "C8D0DD", align: "center", valign: "top",
      lineSpacingMultiple: 1.1
    });
  });

  // Left column - PQ adoption details
  slide.addText("Post-Quantum Adoption", {
    x: 0.4, y: 2.6, w: 4.3, h: 0.35,
    fontSize: 13, fontFace: "Arial",
    color: theme.accent, bold: true
  });

  slide.addText([
    { text: "Chrome 124 enabled PQ key agreement by default (Apr 17, 2024)", options: { fontSize: 10.5, color: "C8D0DD", bullet: { type: "bullet" } } },
    { text: "" },
    { text: "Mozilla Firefox rolling out PQ encryption by default", options: { fontSize: 10.5, color: "C8D0DD", bullet: { type: "bullet" } } },
    { text: "" },
    { text: "Apple Safari began initial PQ testing", options: { fontSize: 10.5, color: "C8D0DD", bullet: { type: "bullet" } } }
  ], {
    x: 0.4, y: 2.95, w: 4.3, h: 1.2,
    valign: "top", paraSpaceAfter: 2
  });

  // API languages sub-section
  slide.addText("API Client Languages", {
    x: 0.4, y: 4.15, w: 4.3, h: 0.35,
    fontSize: 13, fontFace: "Arial",
    color: theme.light, bold: true
  });

  // Mini bar chart using shapes for API languages
  const langs = [
    { name: "Go", pct: 12, color: theme.accent },
    { name: "Python", pct: 9.6, color: "5BA8C8" },
    { name: "Java", pct: 7.4, color: "4A90A0" },
    { name: ".NET", pct: 3.6, color: "3A7080" }
  ];

  langs.forEach((l, i) => {
    const yPos = 4.52 + i * 0.23;
    slide.addText(l.name, {
      x: 0.5, y: yPos, w: 0.7, h: 0.2,
      fontSize: 8, fontFace: "Arial",
      color: "C8D0DD", align: "right", valign: "middle"
    });
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: 1.3, y: yPos + 0.03, w: (l.pct / 12) * 2.5, h: 0.14,
      fill: { color: l.color },
      rectRadius: 0.03
    });
    slide.addText(l.pct + "%", {
      x: 1.3 + (l.pct / 12) * 2.5 + 0.1, y: yPos, w: 0.6, h: 0.2,
      fontSize: 8, fontFace: "Arial",
      color: "C8D0DD", valign: "middle"
    });
  });

  // Right side - PQ encryption chart image
  slide.addImage({
    path: path.resolve(__dirname, "imgs/post-quantum-encryption-adoption.jpg"),
    x: 5.1, y: 2.6, w: 4.5, h: 2.7
  });

  // Caption
  slide.addText("Post-quantum encrypted traffic adoption after Chrome 124 release", {
    x: 5.1, y: 5.25, w: 4.5, h: 0.25,
    fontSize: 8, fontFace: "Arial",
    color: "7A8599", italic: true, align: "center"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a1628", secondary: "1a2a4a", accent: "6ecfef", light: "f48120", bg: "0e1e38" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

