    ["Weather", "8", "3A7080"],
    ["Maintenance", "4", "3A7080"],
    ["Cyber Attack", "4", "3A7080"],
    ["Natural Disaster", "1", "2A5060"],
    ["Fire", "1", "2A5060"]
  ];

  const headerRow = [
    { text: "Cause", options: { fill: { color: theme.accent }, color: theme.primary, bold: true, fontSize: 10, fontFace: "Arial" } },
    { text: "Count", options: { fill: { color: theme.accent }, color: theme.primary, bold: true, fontSize: 10, fontFace: "Arial", align: "center" } },
    { text: "", options: { fill: { color: theme.accent }, color: theme.primary, fontSize: 10 } }
  ];

