      { text: c[0], options: { fill: { color: bgColor }, color: "FFFFFF", fontSize: 9.5, fontFace: "Arial" } },
      { text: c[1], options: { fill: { color: bgColor }, color: c[2], bold: true, fontSize: 10, fontFace: "Arial", align: "center" } },
      { text: "", options: { fill: { color: bgColor }, fontSize: 9.5 } }
    ]);
