    { count: 16, y: 3.31, color: "5BA8C8" },
    { count: 9, y: 3.61, color: "4A90A0" },
    { count: 9, y: 3.91, color: "4A90A0" },
    { count: 8, y: 4.21, color: "3A7080" },
    { count: 4, y: 4.51, color: "3A7080" },
    { count: 4, y: 4.81, color: "3A7080" }
  ];

  barData.forEach(b => {
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: 3.45, y: b.y, w: (b.count / 116) * 1.4, h: 0.16,
      fill: { color: b.color },
      rectRadius: 0.03
    });
  });

  // Right side - disruption image
