    x: 5.2, y: 4.65, w: 2.1, h: 0.7,
    fill: { color: theme.bg },
    rectRadius: 0.06,
    line: { color: theme.accent, width: 0.8 }
  });
  slide.addText("28%", {
    x: 5.2, y: 4.65, w: 2.1, h: 0.4,
    fontSize: 18, fontFace: "Arial",
    color: theme.accent, bold: true, align: "center", valign: "bottom"
  });
  slide.addText("IPv6 Adoption", {
    x: 5.2, y: 5.05, w: 2.1, h: 0.28,
    fontSize: 9, fontFace: "Arial",
    color: "C8D0DD", align: "center", valign: "top"
  });

  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 7.5, y: 4.65, w: 2.1, h: 0.7,
    fill: { color: theme.bg },
    rectRadius: 0.06,
    line: { color: theme.light, width: 0.8 }
  });
  slide.addText("41%", {
    x: 7.5, y: 4.65, w: 2.1, h: 0.4,
    fontSize: 18, fontFace: "Arial",
    color: theme.light, bold: true, align: "center", valign: "bottom"
  });
  slide.addText("Mobile Traffic Share", {
    x: 7.5, y: 5.05, w: 2.1, h: 0.28,
    fontSize: 9, fontFace: "Arial",
    color: "C8D0DD", align: "center", valign: "top"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
