const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 6,
  title: '6.5% of Traffic Mitigated: Persistent Threats and Bot Concentration'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.9,
    fill: { color: theme.bg }
  });
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.1, w: 9, h: 0.7,
    fontSize: 19, fontFace: "Arial",
    color: "FFFFFF", bold: true
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.9, w: 10, h: 0.04,
    fill: { color: theme.accent }
  });

  // Three metric cards across top
  const secMetrics = [
    { val: "6.5%", label: "All Traffic\nMitigated", color: theme.light },
    { val: "4.3%", label: "Emails Flagged\nas Malicious", color: theme.accent },
    { val: "68%", label: "Bot Traffic from\nTop 10 Countries", color: theme.light }
  ];

  secMetrics.forEach((m, i) => {
    const xPos = 0.4 + i * 3.15;
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: xPos, y: 1.15, w: 2.9, h: 1.15,
      fill: { color: theme.bg },
      rectRadius: 0.08,
      line: { color: m.color, width: 1.2 }
    });
    slide.addText(m.val, {
      x: xPos, y: 1.15, w: 2.9, h: 0.6,
      fontSize: 30, fontFace: "Arial",
      color: m.color, bold: true, align: "center", valign: "bottom"
    });
    slide.addText(m.label, {
      x: xPos, y: 1.75, w: 2.9, h: 0.5,
      fontSize: 10, fontFace: "Arial",
      color: "C8D0DD", align: "center", valign: "top",
      lineSpacingMultiple: 1.1
    });
  });

  // Left column - Attack landscape
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.4, y: 2.55, w: 4.5, h: 2.7,
    fill: { color: theme.bg },
    rectRadius: 0.08
  });

  slide.addText("Attack Landscape", {
    x: 0.6, y: 2.6, w: 4, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: theme.accent, bold: true
  });

  slide.addText([
    { text: "Most Attacked Sector:", options: { bold: true, color: theme.light, fontSize: 11, fontFace: "Arial" } },
    { text: "  Gambling & Games", options: { color: "FFFFFF", fontSize: 11, fontFace: "Arial" } }
  ], {
    x: 0.6, y: 3.0, w: 4.1, h: 0.3
  });

  slide.addText([
    { text: "Log4j (CVE-2021-44228)", options: { bold: true, color: "FFFFFF", fontSize: 11, fontFace: "Arial" } },
    { text: " — still actively exploited 2+ years after initial disclosure, underscoring persistent nature of widely known vulnerabilities", options: { color: "C8D0DD", fontSize: 10.5, fontFace: "Arial" } }
  ], {
    x: 0.6, y: 3.35, w: 4.1, h: 0.7,
    valign: "top"
  });

  slide.addText([
    { text: "RPKI valid routes ", options: { bold: true, color: "FFFFFF", fontSize: 11, fontFace: "Arial" } },
    { text: "increased ", options: { color: "C8D0DD", fontSize: 11, fontFace: "Arial" } },
    { text: "6.4%", options: { bold: true, color: theme.accent, fontSize: 11, fontFace: "Arial" } },
    { text: ", improving Internet routing security", options: { color: "C8D0DD", fontSize: 11, fontFace: "Arial" } }
  ], {
    x: 0.6, y: 4.1, w: 4.1, h: 0.35
  });

  // Right column - Email Security
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 5.15, y: 2.55, w: 4.5, h: 2.7,
    fill: { color: theme.bg },
    rectRadius: 0.08
  });

  slide.addText("Email Security Threats", {
    x: 5.35, y: 2.6, w: 4, h: 0.4,
    fontSize: 14, fontFace: "Arial",
    color: theme.light, bold: true
  });

  // Email stats with visual indicators
  const emailStats = [
    { label: "Malicious emails containing deceptive links", val: "43%", color: theme.light },
    { label: "Top malicious/spam TLD origin", val: ".bar", color: theme.accent },
