    x: 0, y: 0, w: 10, h: 0.9,
    fill: { color: theme.bg }
  });
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.1, w: 9, h: 0.7,
    fontSize: 22, fontFace: "Arial",
    color: "FFFFFF", bold: true
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0.9, w: 10, h: 0.04,
    fill: { color: theme.accent }
  });

  const takeaways = [
    {
      num: "1",
      title: "Traffic Growth Trajectory",
      body: "Global Internet traffic grew 17% YoY; Starlink surged 3.3x expanding satellite connectivity to underserved regions.",
      color: theme.light
    },
    {
      num: "2",
      title: "Post-Quantum Momentum",
      body: "Post-quantum encryption leapt from 2% to 13% of TLS 1.3 traffic after Chrome 124 default enablement in April 2024.",
      color: theme.accent
    },
    {
      num: "3",
      title: "Connectivity Fragility",
      body: "Government-directed shutdowns led 225 major disruptions, followed by cable cuts (41) and power outages (16).",
      color: theme.light
    },
    {
      num: "4",
      title: "Persistent Security Threats",
      body: "6.5% of traffic mitigated; Gambling/Games most targeted sector; Log4j exploitation persists years after disclosure.",
      color: theme.accent
    },
    {
      num: "5",
      title: "Evolving Developer Ecosystem",
      body: "Go became the top API client language at ~12% of automated API traffic, reflecting shifts in how developers build for the Internet.",
      color: theme.light
    }
  ];

  takeaways.forEach((t, i) => {
    const yPos = 1.2 + i * 0.85;

    // Number circle
    slide.addShape(pres.shapes.OVAL, {
      x: 0.5, y: yPos + 0.05, w: 0.5, h: 0.5,
      fill: { color: t.color }
    });
    slide.addText(t.num, {
      x: 0.5, y: yPos + 0.05, w: 0.5, h: 0.5,
      fontSize: 18, fontFace: "Arial",
      color: theme.primary, bold: true,
      align: "center", valign: "middle"
    });

    // Title
    slide.addText(t.title, {
      x: 1.2, y: yPos, w: 2.5, h: 0.3,
      fontSize: 13, fontFace: "Arial",
      color: t.color, bold: true
    });

    // Body text
    slide.addText(t.body, {
      x: 1.2, y: yPos + 0.3, w: 8.2, h: 0.45,
      fontSize: 10.5, fontFace: "Arial",
      color: "C8D0DD",
      lineSpacingMultiple: 1.15
    });

    // Subtle divider line (except after last)
    if (i < 4) {
      slide.addShape(pres.shapes.LINE, {
        x: 0.5, y: yPos + 0.8, w: 9, h: 0,
        line: { color: "1a2a4a", width: 0.5 }
      });
    }
  });

  // Bottom accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: 10, h: 0.04,
    fill: { color: theme.light }
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "0a1628", secondary: "1a2a4a", accent: "6ecfef", light: "f48120", bg: "0e1e38" };
